-- Disposable local fixture only. No external Auth, email or production data.
begin;
create temporary table m2_assertions(n integer not null) on commit drop;
insert into m2_assertions values(0);
grant select,update on m2_assertions to authenticated,anon,service_role;
create function pg_temp.m2_ok(v boolean, label text) returns void language plpgsql as $$
begin
  if v is distinct from true then raise exception 'M2 assertion: %',label; end if;
  update m2_assertions set n=n+1;
end;
$$;
create function pg_temp.m2_error(q text, expected text) returns void language plpgsql as $$
declare failed boolean := false;
begin
  begin execute q;
  exception when others then
    if not(sqlstate=any(string_to_array(expected,','))) then raise; end if;
    failed := true;
  end;
  perform pg_temp.m2_ok(failed,'Expected rejection ' || expected);
end;
$$;
